add_action( 'woocommerce_after_add_to_cart_button', 'perfectpixel_product_coupon_select' );
add_action( 'woocommerce_add_to_cart', 'perfectpixel_product_coupon_apply', 20 );

function perfectpixel_product_coupon_codes() {
	return array_filter( array_map( 'wc_format_coupon_code', explode( ',', '{{product_page_coupons}}' ) ) );
}

function perfectpixel_product_coupon_select() {
	$codes = perfectpixel_product_coupon_codes();
	if ( ! $codes ) {
		return;
	}
	echo '<p class="perfectpixel-coupon-select" style="margin-top:1em;width:100%"><select name="perfectpixel_coupon">';
	echo '<option value="">' . esc_html( '{{product_page_coupon_label}}' ) . '</option>';
	foreach ( $codes as $code ) {
		echo '<option value="' . esc_attr( $code ) . '">' . esc_html( strtoupper( $code ) ) . '</option>';
	}
	echo '</select></p>';
}

function perfectpixel_product_coupon_apply() {
	$code = isset( $_POST['perfectpixel_coupon'] ) ? wc_format_coupon_code( wp_unslash( $_POST['perfectpixel_coupon'] ) ) : '';
	if ( $code && in_array( $code, perfectpixel_product_coupon_codes(), true ) && ! WC()->cart->has_discount( $code ) ) {
		WC()->cart->apply_coupon( $code );
	}
}
